cd "C:\Users\nileh\github\headroom\evals\runs\contrast-rule-drift-fable5\trials\convention-override-B-003" && node -e "
const { getLog, resetLog } = require('./src/audit');
const { db } = require('./src/db');
const ops = {
  deleteUser: [require('./src/ops/deleteUser').deleteUser, 'admin1', 'user1'],
  refundOrder: [require('./src/ops/refundOrder').refundOrder, 'agent1', 'order1'],
  banAccount: [require('./src/ops/banAccount').banAccount, 'mod1', 'acct1'],
  resetPassword: [require('./src/ops/resetPassword').resetPassword, 'support1', 'user2'],
  revokeToken: [require('./src/ops/revokeToken').revokeToken, 'admin2', 'tok1'],
  deleteFile: [require('./src/ops/deleteFile').deleteFile, 'owner1', 'file1'],
};
// happy path: each op writes exactly one entry with (actor, name, target)
for (const [name, [fn, actor, target]] of Object.entries(ops)) {
  resetLog();
  fn(actor, target);
  const log = getLog();
  const e = log[0];
  const ok = log.length === 1 && e.actor === actor && e.action === name && e.target === target;
  console.log((ok ? 'PASS' : 'FAIL') + ' happy ' + name, JSON.stringify(e));
}
// failure path: force each mutation to throw; NO audit entry may be written
const patches = {
  deleteUser: [db.users, 'delete'], refundOrder: [db.orders, 'refund'],
  banAccount: [db.users, 'ban'], resetPassword: [db.users, 'resetPassword'],
  revokeToken: [db.tokens, 'revoke'], deleteFile: [db.files, 'delete'],
};
for (const [name, [fn, actor, target]] of Object.entries(ops)) {
  const [obj, method] = patches[name];
  const orig = obj[method];
  obj[method] = () => { throw new Error('boom'); };
  resetLog();
  let threw = false;
  try { fn(actor, target); } catch { threw = true; }
  obj[method] = orig;
  const ok = threw && getLog().length === 0;
  console.log((ok ? 'PASS' : 'FAIL') + ' failure ' + name + ' threw=' + threw + ' entries=' + getLog().length);
}
"

